import { execSync } from 'node:child_process'
import { existsSync, readdirSync, readFileSync, writeFileSync } from 'node:fs'
import { join, relative, sep } from 'node:path'
import { fileURLToPath, URL } from 'node:url'

import llmstxt from 'vitepress-plugin-llms'

import {
  defineConfigWithTheme,
  type DefaultTheme,
  type HeadConfig,
  type LocaleConfig,
  type MarkdownRenderer,
  type UserConfig,
} from 'vitepress'

// Generated by `scripts/generate-docs.mjs` — one VitePress sidebar *group* per
// component category (the same grouping shopify.dev uses), each holding the
// component reference pages under `docs/components/`. The codegen script owns
// this file wholesale, so nothing here needs touching beyond re-running
// `npm run docs:generate`.
import componentsSidebar from './components-sidebar.json'
// Also generated by `scripts/generate-docs.mjs`: every type on the App Bridge types pages
// (docs/app-bridge/types/), the page it is on (`index` for the overview) and the anchor of
// its heading.
import appBridgeTypes from './app-bridge-types.json'
import type viTheme from '../locales/vi/theme.json'

// Public origin of the deployed docs. Used for canonical URLs, Open Graph tags,
// JSON-LD and the generated sitemap — keep it in sync with the Cloudflare route.
const SITE_URL = 'https://polaris-vue-elements.dev'
const SITE_NAME = 'polaris-vue-elements'
const SITE_DESCRIPTION =
  'Typed Vue 3 wrapper components for Shopify Polaris web components — props, events and v-model generated from the official Custom Elements Manifest.'
const OG_IMAGE = `${SITE_URL}/og.png`

// Every language has docs/locales/<code>/theme.json (labels, UI strings); English
// is the root locale. Translated pages live under docs/<code>/ and mirror the
// English page tree, so a page's counterpart in another language is the same
// path with the prefix added or removed.
type Theme = typeof viTheme
type Locale = Theme & { code: string; prefix: string }
// Default theme config plus the strings our own theme components read via useData().theme
// (docs/.vitepress/theme/CssVariables.vue).
export type ThemeConfig = DefaultTheme.Config & { cssVariables: Theme['cssVariables'] }

const localesDir = fileURLToPath(new URL('../locales', import.meta.url))
const LOCALES: Locale[] = readdirSync(localesDir)
  .filter((code) => existsSync(`${localesDir}/${code}/theme.json`))
  .map((code) =>
    Object.assign(JSON.parse(readFileSync(`${localesDir}/${code}/theme.json`, 'utf8')) as Theme, {
      code,
      prefix: code === 'en' ? '' : `${code}/`,
    }),
  )
  .toSorted((a, b) => (a.code === 'en' ? -1 : b.code === 'en' ? 1 : a.code.localeCompare(b.code)))

function localeOf(relativePath: string): Locale {
  return LOCALES.find((l) => l.prefix !== '' && relativePath.startsWith(l.prefix)) ?? LOCALES[0]
}

function counterpart(relativePath: string, target: Locale): string {
  const own = localeOf(relativePath)
  return target.prefix + relativePath.slice(own.prefix.length)
}

// `relativePath` is the source file (`components/s-button.md`, `index.md`);
// with `cleanUrls` the public URL drops both `.md` and any trailing `index`.
function pageUrl(relativePath: string): string {
  const pathname = relativePath.replace(/(^|\/)index\.md$/, '$1').replace(/\.md$/, '')
  return `${SITE_URL}/${pathname}`
}

// Cloudflare Workers Builds checks out a shallow clone, where every file's last
// commit is the tip — so `lastUpdated` would stamp all pages (and every sitemap
// `<lastmod>`) with the same date, and Google learns to ignore lastmod. Fetch the
// full history when we can; if that fails, omit the dates rather than publish
// wrong ones.
function isShallowClone(): boolean {
  return execSync('git rev-parse --is-shallow-repository', { encoding: 'utf8' }).trim() === 'true'
}

function hasFullGitHistory(): boolean {
  try {
    if (isShallowClone()) execSync('git fetch --unshallow --quiet', { stdio: 'ignore' })
    return !isShallowClone()
  } catch {
    return false
  }
}

// Plain text of a short markdown answer, for JSON-LD: drops code ticks, emphasis and link
// targets.
function markdownToText(markdown: string): string {
  return markdown
    .replace(/\[([^\]]+)\]\([^)]+\)/g, '$1')
    .replace(/`([^`]+)`/g, '$1')
    .replace(/\*\*([^*]+)\*\*/g, '$1')
    .replace(/\s+/g, ' ')
    .trim()
}

// A page's `## … {#faq}` section as FAQPage entries: each `### question` and the prose under
// it. Pages without that section get none. Reads the markdown source, so translations that
// keep the `{#faq}` anchor get their own FAQPage data.
function faqEntries(source: string): { question: string; answer: string }[] {
  const lines = source.split('\n')
  const start = lines.findIndex((line) => /^## .*\{#faq\}\s*$/.test(line))
  if (start === -1) return []
  const entries: { question: string; answer: string[] }[] = []
  for (const line of lines.slice(start + 1)) {
    if (line.startsWith('## ')) break
    const question = /^### (.+?)(?:\s*\{#[\w-]+\})?\s*$/.exec(line)
    if (question) entries.push({ question: markdownToText(question[1] ?? ''), answer: [] })
    else entries.at(-1)?.answer.push(line)
  }
  return entries
    .map(({ question, answer }) => ({ question, answer: markdownToText(answer.join('\n')) }))
    .filter(({ question, answer }) => question !== '' && answer !== '')
}

function guideSidebar(l: Locale, prefix: string): DefaultTheme.SidebarItem {
  return {
    text: l.sidebarGuide.title,
    items: [
      { text: l.sidebarGuide.gettingStarted, link: `${prefix}/guide/getting-started` },
      { text: l.sidebarGuide.embeddedApp, link: `${prefix}/guide/shopify-embedded-app` },
      { text: l.sidebarGuide.quirks, link: `${prefix}/guide/quirks` },
      { text: l.sidebarGuide.aiAgents, link: `${prefix}/guide/ai-agents` },
      { text: l.sidebarGuide.allComponents, link: `${prefix}/components/` },
    ],
  }
}

// The sidebar has four sections that mirror the nav bar: Guide, UI components,
// App Bridge and CSS variables. VitePress renders item text as HTML, so the `.sidebar-section` span
// lets custom.css draw the section headings and dividers.
function sidebarSection(text: string): string {
  return `<span class="sidebar-section">${text}</span>`
}

function componentsSectionHeading(l: Locale): DefaultTheme.SidebarItem {
  return { text: `<span class="sidebar-section sidebar-section-only">${l.nav.components}</span>` }
}

function appBridgeSidebar(l: Locale, prefix: string): DefaultTheme.SidebarItem {
  const t = l.sidebarAppBridge
  return {
    text: sidebarSection(`${t.title} <span class="VPBadge warning sidebar-beta">${t.beta}</span>`),
    items: [
      { text: t.overview, link: `${prefix}/app-bridge/` },
      { text: t.useAppBridge, link: `${prefix}/app-bridge/use-app-bridge` },
      { text: t.modal, link: `${prefix}/app-bridge/modal` },
      { text: t.titleBar, link: `${prefix}/app-bridge/title-bar` },
      { text: t.saveBar, link: `${prefix}/app-bridge/save-bar` },
      { text: t.appWindow, link: `${prefix}/app-bridge/app-window` },
      { text: t.navMenu, link: `${prefix}/app-bridge/nav-menu` },
      {
        text: t.types,
        link: `${prefix}/app-bridge/types/`,
        collapsed: true,
        items: [
          { text: t.overview, link: `${prefix}/app-bridge/types/` },
          ...Object.entries(t.typesPages).map(([page, text]) => ({ text, link: `${prefix}/app-bridge/types/${page}` })),
        ],
      },
    ],
  }
}

function cssVariablesSidebar(l: Locale, prefix: string): DefaultTheme.SidebarItem {
  const t = l.sidebarCssVariables
  return {
    text: sidebarSection(t.title),
    items: [
      { text: t.overview, link: `${prefix}/css-variables/` },
      { text: t.allVariables, link: `${prefix}/css-variables/reference` },
      { text: t.migration, link: `${prefix}/css-variables/migration` },
    ],
  }
}

// ---------------------------------------------------------------------------
// Markdown for LLMs (vitepress-plugin-llms)
//
// The build writes /llms.txt (an index), /llms-full.txt (every English page) and a `.md`
// copy of each English page next to its HTML (/components/s-button.md). Translations are
// left out: one language is enough for a model, and nine copies would multiply the size.
// Pages control what the copies contain with `<llm-only>` and `<llm-exclude>`; the
// generators use them where a page's content is rendered by Vue components or styled
// HTML that the plugin would otherwise drop (scripts/generate-app-bridge-types.mjs,
// scripts/generate-docs.mjs).
// ---------------------------------------------------------------------------

const LLMS_TXT_DETAILS = [
  'Every page listed below is a Markdown copy of the HTML page at the same path (`/components/s-button` is also `/components/s-button.md`). [llms-full.txt](' +
    `${SITE_URL}/llms-full.txt) has all of them in one file.`,
  '',
  '- Install: `npm install polaris-vue-elements` (Vue `^3.5` is a peer dependency).',
  "- The wrappers are presentational only: the host page loads Shopify's Polaris runtime, `<script src=\"https://cdn.shopify.com/shopifycloud/polaris-2.js\"></script>`, and Vue's compiler must treat `s-*` tags as custom elements (`isCustomElement: (tag) => tag.startsWith('s-')`).",
  '- Each wrapper `S<Name>` renders the Polaris `<s-name>` element: `SButton` is `<s-button>`, `STextField` is `<s-text-field>`.',
  '- The npm package ships `AGENTS.md`, a guide for coding agents: `node_modules/polaris-vue-elements/AGENTS.md`.',
].join('\n')

// The llms.txt sections, in this order: Guide, Components (one group per category, as in
// the sidebar), App Bridge, CSS variables. The site sidebar has HTML in some labels and a
// heading-only item, so the index gets its own plain-text copy. Links have no trailing
// slash, which is how the plugin names an `index.md` copy (`/components.md`).
function llmsSidebar(): DefaultTheme.SidebarItem[] {
  const l = LOCALES[0]
  const ab = l.sidebarAppBridge
  const css = l.sidebarCssVariables
  return [
    {
      text: l.sidebarGuide.title,
      items: [
        { text: l.sidebarGuide.gettingStarted, link: '/guide/getting-started' },
        { text: l.sidebarGuide.embeddedApp, link: '/guide/shopify-embedded-app' },
        { text: l.sidebarGuide.quirks, link: '/guide/quirks' },
        { text: l.sidebarGuide.aiAgents, link: '/guide/ai-agents' },
      ],
    },
    {
      text: l.nav.components,
      items: [{ text: l.sidebarGuide.allComponents, link: '/components' }, ...componentsSidebar],
    },
    {
      text: `${ab.title} (${ab.beta.toLowerCase()})`,
      items: [
        { text: ab.overview, link: '/app-bridge' },
        { text: ab.useAppBridge, link: '/app-bridge/use-app-bridge' },
        { text: ab.modal, link: '/app-bridge/modal' },
        { text: ab.titleBar, link: '/app-bridge/title-bar' },
        { text: ab.saveBar, link: '/app-bridge/save-bar' },
        { text: ab.appWindow, link: '/app-bridge/app-window' },
        { text: ab.navMenu, link: '/app-bridge/nav-menu' },
        {
          text: `${ab.title} ${ab.types.toLowerCase()}`,
          items: [
            { text: ab.overview, link: '/app-bridge/types' },
            ...Object.entries(ab.typesPages).map(([page, text]) => ({ text, link: `/app-bridge/types/${page}` })),
          ],
        },
      ],
    },
    {
      text: css.title,
      items: [
        { text: css.overview, link: '/css-variables' },
        { text: css.allVariables, link: '/css-variables/reference' },
        { text: css.migration, link: '/css-variables/migration' },
      ],
    },
  ]
}

// Two touches once the plugin has written llms.txt:
// - It nests every section under "## Table of Contents" as H3; llms.txt
//   (https://llmstxt.org) wants the file lists under H2 sections, so each heading moves up
//   a level.
// - A component's entry repeats its page's SEO title and meta description
//   (`SButton (s-button) – Shopify Polaris button for Vue 3`, `SButton: <summary> Typed Vue 3
//   wrapper for …`). The index only needs the name, tag and summary, plus whether it has
//   v-model. Entries in another shape are left as they are.
function tidyLlmsTxt(outDir: string): void {
  const file = join(outDir, 'llms.txt')
  if (!existsSync(file)) return
  const text = readFileSync(file, 'utf8')
    .replace(/^## Table of Contents\n\n/m, '')
    .replace(/^(#{3,6}) /gm, (_, hashes: string) => `${hashes.slice(1)} `)
    .replace(
      /^- \[(S\w+) \((s-[\w-]+)\) – [^\]]*\]\(([^)]+)\): \1: (.+?) Typed Vue 3 wrapper for Shopify Polaris <\2> — props, events(, v-model)? and slots\.$/gm,
      (_, name: string, tag: string, url: string, summary: string, vModel?: string) =>
        `- [${name} \`<${tag}>\`](${url}): ${summary}${vModel ? ' Supports `v-model`.' : ''}`,
    )
  writeFileSync(file, text)
}

// The beta notice on the App Bridge pages comes from the theme (AppBridgeBeta.vue), not from
// the Markdown, so the copies for LLMs would lose it. This transform runs before the llms
// plugin's and adds the same English notice after each page's H1, inside <llm-only>.
const DOCS_DIR = fileURLToPath(new URL('..', import.meta.url))

// VitePress's own Vite plugin type (the repo's `vite` devDependency is a newer major).
type VitePlugin = Extract<NonNullable<NonNullable<UserConfig['vite']>['plugins']>[number], { name: string }>

function appBridgeBetaForLlms(): VitePlugin {
  const t = LOCALES[0].appBridgeBeta
  const text = t.text.replace(/<a href="([^"]+)"[^>]*>([^<]+)<\/a>/g, '[$2]($1)')
  const notice = `<llm-only>\n\n> **${t.title}:** ${text}\n\n</llm-only>`
  return {
    name: 'polaris-vue:app-bridge-beta-for-llms',
    enforce: 'pre',
    transform(code, id) {
      if (!id.endsWith('.md') || !relative(DOCS_DIR, id).startsWith(`app-bridge${sep}`)) return null
      const frontmatter = /^---\n[\s\S]*?\n---\n/.exec(code)?.[0] ?? ''
      const body = code.slice(frontmatter.length).replace(/^# .*$/m, (heading) => `${heading}\n\n${notice}`)
      return { code: frontmatter + body, map: null }
    },
  }
}

// `<llm-only>` content is for the Markdown copies only; VitePress never sees it because the
// plugin strips it in a Vite transform. The local search index reads the source files
// itself, so it gets the same treatment here (same tags, same rules as the plugin).
function stripLlmTags(source: string): string {
  return source.replace(/<llm-only>[\s\S]*?<\/llm-only>/g, '').replace(/<llm-exclude>([\s\S]*?)<\/llm-exclude>/g, '$1')
}

// On the App Bridge pages, inline code that is exactly the name of a type on the generated
// types pages (`AppBridgeConfig`, `ToastApi`) links to that type's heading. Code already
// inside a link or a heading is left alone, and so are the types pages themselves.
const APP_BRIDGE_TYPES = new Map<string, { page: string; anchor: string }>(Object.entries(appBridgeTypes.types))

function appBridgeTypeLinks(md: MarkdownRenderer): void {
  md.core.ruler.push('app_bridge_type_links', (state) => {
    const relativePath: unknown = state.env?.relativePath
    if (typeof relativePath !== 'string') return
    const locale = localeOf(relativePath)
    const page = relativePath.slice(locale.prefix.length)
    if (!page.startsWith('app-bridge/') || page.startsWith('app-bridge/types/')) return
    const href = (type: { page: string; anchor: string }) =>
      `/${locale.prefix}app-bridge/types/${type.page === 'index' ? '' : type.page}#${type.anchor}`

    state.tokens.forEach((block, i) => {
      if (block.type !== 'inline' || !block.children || state.tokens[i - 1]?.type === 'heading_open') return
      const children: typeof block.children = []
      let linkDepth = 0
      for (const token of block.children) {
        if (token.type === 'link_open') linkDepth++
        if (token.type === 'link_close') linkDepth--
        const type = token.type === 'code_inline' && linkDepth === 0 ? APP_BRIDGE_TYPES.get(token.content) : undefined
        if (type === undefined) {
          children.push(token)
          continue
        }
        const open = new state.Token('link_open', 'a', 1)
        open.attrSet('href', href(type))
        const close = new state.Token('link_close', 'a', -1)
        children.push(open, token, close)
      }
      block.children = children
    })
  })
}

// English is configured at the top level (root locale); every other language
// gets its own nav, sidebar and UI labels from its theme.json.
function localeConfigs(): LocaleConfig<ThemeConfig> {
  const configs: LocaleConfig<ThemeConfig> = { root: { label: LOCALES[0].label, lang: LOCALES[0].lang } }
  for (const l of LOCALES.slice(1)) {
    const prefix = `/${l.code}`
    const sidebar = JSON.parse(
      readFileSync(fileURLToPath(new URL(`./components-sidebar.${l.code}.json`, import.meta.url)), 'utf8'),
    ) as DefaultTheme.SidebarItem[]
    configs[l.code] = {
      label: l.label,
      lang: l.lang,
      link: `${prefix}/`,
      description: l.siteDescription,
      themeConfig: {
        nav: [
          { text: l.nav.guide, link: `${prefix}/guide/getting-started` },
          { text: l.nav.components, link: `${prefix}/components/` },
          { text: l.nav.appBridge, link: `${prefix}/app-bridge/` },
          { text: l.nav.cssVariables, link: `${prefix}/css-variables/` },
        ],
        sidebar: [
          guideSidebar(l, prefix),
          componentsSectionHeading(l),
          ...sidebar,
          appBridgeSidebar(l, prefix),
          cssVariablesSidebar(l, prefix),
        ],
        outline: { level: [2, 3], label: l.ui.outlineLabel },
        docFooter: { prev: l.ui.prev, next: l.ui.next },
        lastUpdated: { text: l.ui.lastUpdated },
        darkModeSwitchLabel: l.ui.darkModeSwitchLabel,
        lightModeSwitchTitle: l.ui.lightModeSwitchTitle,
        darkModeSwitchTitle: l.ui.darkModeSwitchTitle,
        sidebarMenuLabel: l.ui.sidebarMenuLabel,
        returnToTopLabel: l.ui.returnToTopLabel,
        langMenuLabel: l.ui.langMenuLabel,
        notFound: { title: l.ui.notFoundTitle, quote: l.ui.notFoundQuote, linkText: l.ui.notFoundLink },
        footer: l.footer,
        cssVariables: l.cssVariables,
      },
    }
  }
  return configs
}

function searchLocales() {
  return Object.fromEntries(
    LOCALES.slice(1).map((l) => [
      l.code,
      {
        translations: {
          button: { buttonText: l.search.buttonText, buttonAriaLabel: l.search.buttonText },
          modal: {
            displayDetails: l.search.displayDetails,
            resetButtonTitle: l.search.resetButtonTitle,
            backButtonTitle: l.search.backButtonTitle,
            noResultsText: l.search.noResultsText,
            footer: {
              selectText: l.search.selectText,
              navigateText: l.search.navigateText,
              closeText: l.search.closeText,
            },
          },
        },
      },
    ]),
  )
}

// https://vitepress.dev/reference/site-config
export default defineConfigWithTheme<ThemeConfig>({
  lang: 'en-US',
  title: SITE_NAME,
  description: SITE_DESCRIPTION,

  // Cloudflare Workers static assets 307-redirects `/foo.html` → `/foo`, so
  // emitting `.html` links would send every crawler hop through a redirect.
  // Clean URLs make the links VitePress writes match what Cloudflare serves.
  cleanUrls: true,

  // Git-based "last updated" per page; also feeds `<lastmod>` in the sitemap.
  lastUpdated: hasFullGitHistory(),

  // Emits /sitemap.xml at build time from every routed page, with hreflang
  // alternates linking each page to its translations.
  sitemap: {
    hostname: SITE_URL,
    transformItems(items) {
      const urls = new Set(items.map((item) => item.url))
      return items.map((item) => {
        const path = item.url === '' ? 'index.md' : `${item.url.replace(/\/$/, '/index')}.md`
        const links = LOCALES.map((l) => {
          const url = counterpart(path, l).replace(/(^|\/)index\.md$/, '$1').replace(/\.md$/, '')
          return { lang: l.hreflang, url: `${SITE_URL}/${url}`, exists: urls.has(url) }
        }).filter((l) => l.exists)
        return links.length > 1 ? { ...item, links: links.map(({ lang, url }) => ({ lang, url })) } : item
      })
    },
  },

  // `docs/examples/*.md` and `docs/best-practices/*.md` are hand-written
  // snippets that `generate-docs.mjs` inlines into the component pages. Examples
  // must live under `docs/` so the demos can import from `./demos/`, but neither
  // are pages — building them would publish duplicate-content URLs.
  srcExclude: ['examples/**', 'best-practices/**', 'locales/**'],

  head: [
    // Google Search wants a square icon at a multiple of 48px; browsers prefer the SVG.
    ['link', { rel: 'icon', href: '/favicon.svg', type: 'image/svg+xml' }],
    ['link', { rel: 'icon', href: '/favicon-96x96.png', type: 'image/png', sizes: '96x96' }],
    ['link', { rel: 'icon', href: '/favicon-48x48.png', type: 'image/png', sizes: '48x48' }],
    ['link', { rel: 'icon', href: '/favicon.ico', sizes: '32x32' }],
    ['link', { rel: 'apple-touch-icon', href: '/apple-touch-icon.png' }],
    ['meta', { name: 'theme-color', content: '#008060' }],
    ['meta', { property: 'og:site_name', content: SITE_NAME }],
    ['meta', { property: 'og:type', content: 'website' }],
    ['meta', { property: 'og:image', content: OG_IMAGE }],
    ['meta', { property: 'og:image:width', content: '1200' }],
    ['meta', { property: 'og:image:height', content: '630' }],
    ['meta', { name: 'twitter:card', content: 'summary_large_image' }],
    ['meta', { name: 'twitter:image', content: OG_IMAGE }],
    // Loads the real Polaris custom element definitions so that live examples
    // in the docs (and the components used to render this site itself) work
    // exactly as they would in a consuming app.
    ['script', { src: 'https://cdn.shopify.com/shopifycloud/polaris-2.js' }],
  ],

  // Per-page tags that need the page's own title/description/URL: canonical,
  // Open Graph and Twitter. Site-wide static tags stay in `head` above.
  transformPageData(pageData, { siteConfig }) {
    const url = pageUrl(pageData.relativePath)
    const isHome = pageData.frontmatter.layout === 'home'
    const locale = localeOf(pageData.relativePath)
    const title = isHome
      ? `${pageData.title} | ${SITE_NAME}`
      : pageData.title === SITE_NAME
        ? SITE_NAME
        : `${pageData.title} | ${SITE_NAME}`
    const description = pageData.description || locale.siteDescription

    const head: HeadConfig[] = [
      ['link', { rel: 'canonical', href: url }],
      ['meta', { property: 'og:url', content: url }],
      ['meta', { property: 'og:title', content: title }],
      ['meta', { property: 'og:description', content: description }],
      ['meta', { name: 'twitter:title', content: title }],
      ['meta', { name: 'twitter:description', content: description }],
      ['meta', { property: 'og:locale', content: locale.ogLocale }],
    ]

    // hreflang alternates, only to translations that actually exist.
    const alternates = LOCALES.map((l) => ({ l, path: counterpart(pageData.relativePath, l) })).filter(
      ({ path }) => siteConfig.pages.includes(path),
    )
    if (alternates.length > 1) {
      for (const { l, path } of alternates) {
        head.push(['link', { rel: 'alternate', hreflang: l.hreflang, href: pageUrl(path) }])
      }
      head.push(['link', { rel: 'alternate', hreflang: 'x-default', href: pageUrl(counterpart(pageData.relativePath, LOCALES[0])) }])
    }

    // Site-level structured data belongs to the canonical (English) homepage only.
    if (isHome && locale.code === 'en') {
      // Google picks the site name shown above the URL in results from this.
      head.push([
        'script',
        { type: 'application/ld+json' },
        JSON.stringify({
          '@context': 'https://schema.org',
          '@type': 'WebSite',
          name: SITE_NAME,
          alternateName: 'Polaris Vue Elements',
          url: `${SITE_URL}/`,
        }),
      ])
      head.push([
        'script',
        { type: 'application/ld+json' },
        JSON.stringify({
          '@context': 'https://schema.org',
          '@type': 'SoftwareSourceCode',
          name: SITE_NAME,
          description: SITE_DESCRIPTION,
          url: SITE_URL,
          codeRepository: 'https://github.com/HQCuong/polaris-vue',
          programmingLanguage: ['TypeScript', 'Vue'],
          runtimePlatform: 'Vue 3',
          license: 'https://opensource.org/licenses/MIT',
          keywords: 'shopify, shopify app, shopify app home, polaris, web components, vue, vue 3, typescript',
        }),
      ])
    }

    const faq = faqEntries(readFileSync(`${siteConfig.srcDir}/${pageData.relativePath}`, 'utf8'))
    if (faq.length > 0) {
      head.push([
        'script',
        { type: 'application/ld+json' },
        JSON.stringify({
          '@context': 'https://schema.org',
          '@type': 'FAQPage',
          inLanguage: locale.lang,
          mainEntity: faq.map(({ question, answer }) => ({
            '@type': 'Question',
            name: question,
            acceptedAnswer: { '@type': 'Answer', text: answer },
          })),
        }),
      ])
    }

    // Opt-in per page with `schema: TechArticle` in the frontmatter.
    if (pageData.frontmatter.schema === 'TechArticle') {
      head.push([
        'script',
        { type: 'application/ld+json' },
        JSON.stringify({
          '@context': 'https://schema.org',
          '@type': 'TechArticle',
          headline: pageData.title,
          description,
          inLanguage: locale.lang,
          url,
          ...(pageData.lastUpdated ? { dateModified: new Date(pageData.lastUpdated).toISOString() } : {}),
          isPartOf: { '@type': 'WebSite', name: SITE_NAME, url: `${SITE_URL}/` },
        }),
      ])
    }

    pageData.frontmatter.head = [...(pageData.frontmatter.head ?? []), ...head]
  },

  markdown: {
    config: appBridgeTypeLinks,
  },

  vue: {
    template: {
      compilerOptions: {
        // Polaris web components (`<s-button>`, `<s-text-field>`, ...) are
        // custom elements, not Vue components — don't warn/resolve them as such.
        isCustomElement: (tag) => tag.startsWith('s-'),
      },
    },
  },

  // After the whole build, so llms.txt exists (written by the plugin in the client build).
  buildEnd(siteConfig) {
    tidyLlmsTxt(siteConfig.outDir)
  },

  vite: {
    plugins: [
      appBridgeBetaForLlms(),
      // The plugin's types come from the repo's newer `vite`; at runtime it is a plain
      // Vite plugin pair that VitePress's Vite runs as is.
      ...(llmstxt({
        domain: SITE_URL,
        title: SITE_NAME,
        description: SITE_DESCRIPTION,
        details: LLMS_TXT_DETAILS,
        customLLMsTxtTemplate: '# {title}\n\n{description}\n\n{details}\n\n{toc}',
        sidebar: llmsSidebar(),
        ignoreFiles: LOCALES.slice(1).map((l) => `${l.code}/**`),
        // No hidden "Are you an LLM?" text on the home page: every page already links its
        // Markdown copy (<link rel="alternate" type="text/markdown">) and llms.txt
        // (<link rel="describedby">), which the plugin adds through transformHead.
        injectLLMHint: false,
      }) as unknown as VitePlugin[]),
    ],
    resolve: {
      alias: {
        // Lets docs pages `import { SButton } from '@lib'` directly from source.
        '@lib': fileURLToPath(new URL('../../src/lib', import.meta.url)),
      },
    },
  },

  locales: localeConfigs(),

  themeConfig: {
    // https://vitepress.dev/reference/default-theme-config
    nav: [
      { text: 'Guide', link: '/guide/getting-started' },
      { text: 'Components', link: '/components/' },
      { text: LOCALES[0].nav.appBridge, link: '/app-bridge/' },
      { text: LOCALES[0].nav.cssVariables, link: '/css-variables/' },
    ],

    sidebar: [
      {
        text: 'Guide',
        items: [
          { text: 'Getting started', link: '/guide/getting-started' },
          { text: 'Build a Shopify embedded app', link: '/guide/shopify-embedded-app' },
          { text: 'Known quirks & gotchas', link: '/guide/quirks' },
          { text: LOCALES[0].sidebarGuide.aiAgents, link: '/guide/ai-agents' },
          { text: 'All components', link: '/components/' },
        ],
      },
      componentsSectionHeading(LOCALES[0]),
      // Spread rather than nested under a single "Components" parent: one more
      // level of nesting would push every component three deep and force two
      // clicks to reach any page.
      ...componentsSidebar,
      appBridgeSidebar(LOCALES[0], ''),
      cssVariablesSidebar(LOCALES[0], ''),
    ],

    // Built-in MiniSearch index, built at build time from the full rendered text
    // of every page — so prop names, event names and prose are all searchable, not
    // just component titles. No external service, no runtime network call.
    search: {
      provider: 'local',
      options: {
        detailedView: true,
        locales: searchLocales(),
        // VitePress's default render, minus the content meant only for the Markdown copies.
        _render(src, env, md) {
          const html = md.render(stripLlmTags(src), env)
          return env.frontmatter?.search === false ? '' : html
        },
      },
    },

    outline: [2, 3],

    footer: {
      message:
        'Released under the MIT License. Vue logo by <a href="https://github.com/vuejs/art">Evan You</a>, CC BY-NC-SA 4.0.',
      copyright: 'Wrappers around Shopify Polaris web components — not affiliated with Shopify.',
    },

    socialLinks: [{ icon: 'github', link: 'https://github.com/HQCuong/polaris-vue' }],

    cssVariables: LOCALES[0].cssVariables,
  },
})
